import { VIS_AR } from "./visualsAr";
/** Fixed words inside composed cells, in the screen language (record names and codes stay as stored). */
const W = (s: Scope, en: string) => (s.ar ? VIS_AR[en] ?? en : en);

export interface VisualDef { id: string; ws: string; slot: "primary" | "secondary"; title: Bi; meaning: Bi; sources: string[]; shape: DataShape; view: ViewKind; w: Width; h?: Height | undefined; options?: WidgetOption[] | undefined; data: (s: Scope, o: Record<string, string>) => WidgetData }

const day = (v: unknown) => String(v ?? "").slice(0, 10);
const addDays = (d: string, n: number) => new Date(Date.parse(`${d}T00:00:00Z`) + n * 86400000).toISOString().slice(0, 10);
const ageOf = (v: unknown, on: string) => { const d = day(v); return d ? Math.max(0, Math.round((Date.parse(on) - Date.parse(d)) / 86400000)) : 0; };
const AGE: [number, string][] = [[30, "0–30"], [60, "31–60"], [90, "61–90"], [Infinity, "90+"]];
const ageBucket = (a: number) => AGE.find(([m]) => a <= m)![1];
const list_ = (doctype: string, filters?: [string, string, unknown][]): CDrill => ({ kind: "list", doctype, ...(filters ? { filters } : {}) });
const doc_ = (doctype: string, name: string): CDrill => ({ kind: "doc", doctype, name });
const p360 = (project: string): CDrill => ({ kind: "page", to: `project/${encodeURIComponent(project)}` });
const NA = (shape: "series" | "rows" | "matrix" | "xy", reason: Bi): WidgetData => shape === "series" ? { kind: "series", status: "unavailable", points: [], reason } : shape === "rows" ? { kind: "rows", status: "unavailable", columns: [], rows: [], reason } : shape === "matrix" ? { kind: "matrix", status: "unavailable", rowKeys: [], colKeys: [], values: [], reason } : { kind: "xy", status: "unavailable", points: [], axes: { x: ["", ""], y: ["", ""], size: ["", ""] }, reason };
const NO_SOURCE = (what: string, whatAr: string): Bi => [`The supplied source has no ${what}.`, `لا يحتوي المصدر المورد على ${whatAr}.`];
const series = (points: SeriesPoint[], valueLabel?: Bi, extra: Partial<Extract<WidgetData, { kind: "series" }>> = {}): WidgetData => ({ kind: "series", status: points.length ? "ok" : "empty", points, ...(valueLabel ? { valueLabel } : {}), ...extra });
const rowsData = (columns: Extract<WidgetData, { kind: "rows" }>["columns"], rs: WidgetRow[], extra: Partial<Extract<WidgetData, { kind: "rows" }>> = {}): WidgetData => ({ kind: "rows", status: rs.length ? "ok" : "empty", columns, rows: rs, ...extra });
/** `rowDrill`: the record a row stands for (project, crew, machine, package …); its label opens it (Phase 4 C4-01). */
function matrix(rowKeys: string[], colKeys: string[], cell: (r: string, c: string) => number, rowDrill?: (r: string) => CDrill | undefined): WidgetData {
  const values = rowKeys.map((r) => colKeys.map((c) => r2(cell(r, c))));
  // a grid of zeros (e.g. the 5×5 risk matrix with no open risk) is empty, not a chart of nothing
  const any = values.some((row) => row.some((v) => v !== 0));
  return { kind: "matrix", status: any ? "ok" : "empty", rowKeys: any ? rowKeys : [], colKeys, values, ...(rowDrill && any ? { rowDrill: rowKeys.map(rowDrill) } : {}) };
}
/** Shows names instead of record codes on matrix rows (labels kept unique; values unchanged). */
function named(d: WidgetData, label: (k: string) => string): WidgetData {
  if (d.kind !== "matrix") return d; const seen = new Map<string, number>();
  return { ...d, rowKeys: d.rowKeys.map((k) => { const l = label(k) || k; const n = (seen.get(l) ?? 0) + 1; seen.set(l, n); return n > 1 ? `${l} (${n})` : l; }) };
}
const group = <T,>(xs: T[], k: (x: T) => string) => { const m = new Map<string, T[]>(); for (const x of xs) { const kk = k(x) || "—"; m.set(kk, [...(m.get(kk) ?? []), x]); } return m; };
const top = (pts: SeriesPoint[], nMax = 10) => [...pts].sort((a, b) => b.value - a.value).slice(0, nMax);
const MONEY: Bi = ["Amount", "المبلغ"]; const COUNT: Bi = ["Records", "السجلات"];
/** Drill filters for the widget period (same window inPeriod applies, ending on the scope date), so a drill lists the rows the figure sums. */
const periodFilters = (field: string, o: Record<string, string>, on: string): [string, string, unknown][] => {
  const n = Number(o["period"]); if (!o["period"] || o["period"] === "all" || !Number.isFinite(n)) return [];
  return [[field, ">=", addDays(on, -n)], [field, "<=", on]];
};
const projName = (p: string) => projectTitle(get("Project", p), true) || p;
/** Supplier / subcontractor display name (names, not codes); the code when the record has no name. */
const supName = (code: unknown) => { const c = String(code ?? ""); return String(get("Supplier", c)?.["supplier_name"] ?? "") || c; };
const custName = (code: unknown) => customerName(code, true) || String(code ?? "");
/** Cost code with its description in the screen language ("CC-04.01 · Concrete"); the code alone when it has none. */
const codeName = (code: string, s: Scope) => { const c = list("Digit Cost Code", (x) => x.name === code || x["code"] === code)[0]; const d = String((s.ar ? c?.["description_ar"] : undefined) || c?.["description"] || ""); return d && d !== code ? `${code} · ${d}` : code; };
/** One project to chart when a visual needs a single project: the dashboard project filter, else the first in scope. */
const oneProject = (s: Scope) => s.project ?? projectsOf(s)[0]?.name;
const pickNote = (s: Scope): Bi | undefined => (s.project ? undefined : ["Showing the first construction project; choose a project in the dashboard filter to change it.", "يُعرض أول مشروع مقاولات؛ اختر مشروعًا من مرشح اللوحة لتغييره."]);
const workflowStates = (dt: string) => CONSTRUCTION_WORKFLOWS.find((w) => w.document_type === dt)?.states.map((x) => x.state) ?? [];

const V = (ws: string, slot: "primary" | "secondary", title: Bi, meaning: Bi, sources: string[], shape: DataShape, view: ViewKind, w: Width, data: VisualDef["data"], options?: WidgetOption[]): VisualDef => ({ id: `${ws}:${slot}`, ws, slot, title, meaning, sources, shape, view, w, h: 2, ...(options ? { options } : {}), data });

