const monthsBack = (on: string, n: number) => { const out: string[] = []; let m = on.slice(0, 7); for (let i = 0; i < n; i++) { out.unshift(m); const [y, mm] = m.split("-").map(Number) as [number, number]; m = mm === 1 ? `${y - 1}-12` : `${y}-${String(mm - 1).padStart(2, "0")}`; } return out; };
