export const deptVisual = (id: string) => DEPT_VISUALS.find((v) => v.id === id);

/* ------------------------------------------------------------------ helpers ------------------------------------------------------------------ */
const dur = (t: { start: string; end: string }) => Math.max(1, Math.round((Date.parse(t.end) - Date.parse(t.start)) / 86400000) + 1);
const nextMonth = (m: string) => { const [y, mm] = m.split("-").map(Number) as [number, number]; return mm === 12 ? `${y + 1}-01` : `${y}-${String(mm + 1).padStart(2, "0")}`; };
const monthEnd = (m: string) => { const [y, mm] = m.split("-").map(Number) as [number, number]; return new Date(Date.UTC(y, mm, 0)).toISOString().slice(0, 10); };
function latestUpdate(ups: Doc[], task: string, by: string) { const u = ups.filter((x) => x["task"] === task && day(x["update_date"]) <= by).sort((a, b) => day(b["update_date"]).localeCompare(day(a["update_date"])))[0]; return u ? Math.max(0, Math.min(100, num(u["progress_pct"]))) : 0; }
const contractsOfScope = (s: Scope) => { const ps = new Set(projectsOf(s).map((p) => p.name)); return list("Digit Client Contract", (c) => ps.has(String(c["project"])) && c["workflow_state"] !== "Draft" && num(c.docstatus) !== 2); };
const positionsOf = (s: Scope) => contractsOfScope(s).map(contractPosition);
function decisionStates(s: Scope) {
  let all = 0, awaiting = 0, decided = 0; const waiting: Doc[] = [];
  for (const w of CONSTRUCTION_WORKFLOWS) {
    const decide = new Set(w.transitions.filter((t) => DECISIONS.has(t.action)).map((t) => t.state));
    const first = w.states[0]?.state;
    for (const d of docs(w.document_type, s)) {
      all++; const st = String(d[w.workflow_state_field] ?? first ?? "");
      if (st === first && num(d.docstatus) === 0) continue;
      if (decide.has(st)) { awaiting++; waiting.push(d); } else decided++;
    }
  }
  return { all, awaiting, decided, waiting };
}
function retentionRows(s: Scope, stream?: "client" | "subcontract"): WidgetData {
  const ss = projectsOf(s).flatMap((p) => schedulesOf(p.name, s.on)).filter((x) => x.kind === "retention" && (!stream || x.stream === stream));
  const mv = ss.flatMap((x) => x.movements.map((m) => ({ x, m }))).sort((a, b) => b.m.date.localeCompare(a.m.date)).slice(0, 25);
  return rowsData([{ key: "what", label: ["Movement", "الحركة"], data: true }, { key: "amount", label: ["Amount", "المبلغ"], numeric: true }, { key: "balance", label: ["Balance", "الرصيد"], numeric: true }],
    mv.map(({ x, m }) => ({ id: m.key, date: m.date || undefined, cells: { what: `${W(s, m.kind)} · ${x.contract_title || x.contract}`, amount: m.amount, balance: m.balance }, drill: m.doctype && m.name ? doc_(m.doctype, m.name) : undefined, tone: m.kind === "released" ? "ok" as const : undefined })));
}
